Here's a complete checkout page implementation in React + TypeScript with plain CSS.

## `types.ts`

```tsx
export interface CartItem {
  id: string;
  name: string;
  imageUrl: string;
  unitPrice: number;
  quantity: number;
}

export interface DeliveryAddress {
  fullName: string;
  email: string;
  phone: string;
  street: string;
  houseNumber: string;
  apartment?: string;
  city: string;
  postalCode: string;
  country: string;
}

export type AddressErrors = Partial<Record<keyof DeliveryAddress, string>>;
```

## `CheckoutPage.tsx`

```tsx
import React, { useMemo, useState } from "react";
import { CartItem, DeliveryAddress, AddressErrors } from "./types";
import "./CheckoutPage.css";

interface CheckoutPageProps {
  items: CartItem[];
  onBackToCart: () => void;
  onPay: (address: DeliveryAddress) => Promise<void> | void;
  shippingCost?: number;
  currency?: string;
}

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: "",
  email: "",
  phone: "",
  street: "",
  houseNumber: "",
  apartment: "",
  city: "",
  postalCode: "",
  country: "",
};

function formatPrice(value: number, currency: string): string {
  return new Intl.NumberFormat(undefined, {
    style: "currency",
    currency,
  }).format(value);
}

function validateAddress(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};

  if (!address.fullName.trim()) errors.fullName = "Full name is required.";

  if (!address.email.trim()) {
    errors.email = "Email is required.";
  } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(address.email)) {
    errors.email = "Enter a valid email address.";
  }

  if (!address.phone.trim()) errors.phone = "Phone number is required.";

  if (!address.street.trim()) errors.street = "Street is required.";

  if (!address.houseNumber.trim())
    errors.houseNumber = "House number is required.";

  if (!address.city.trim()) errors.city = "City is required.";

  if (!address.postalCode.trim()) {
    errors.postalCode = "Postal code is required.";
  }

  if (!address.country.trim()) errors.country = "Country is required.";

  return errors;
}

export const CheckoutPage: React.FC<CheckoutPageProps> = ({
  items,
  onBackToCart,
  onPay,
  shippingCost = 4.99,
  currency = "USD",
}) => {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<AddressErrors>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.unitPrice * item.quantity, 0),
    [items]
  );

  const total = useMemo(
    () => (items.length > 0 ? subtotal + shippingCost : 0),
    [subtotal, shippingCost, items.length]
  );

  const handleChange =
    (field: keyof DeliveryAddress) =>
    (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
      const { value } = e.target;
      setAddress((prev) => ({ ...prev, [field]: value }));
      setErrors((prev) => ({ ...prev, [field]: undefined }));
    };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSubmitError(null);

    if (items.length === 0) {
      setSubmitError("Your cart is empty.");
      return;
    }

    const validationErrors = validateAddress(address);
    setErrors(validationErrors);

    if (Object.keys(validationErrors).length > 0) {
      return;
    }

    try {
      setIsSubmitting(true);
      await onPay(address);
    } catch (err) {
      setSubmitError(
        err instanceof Error
          ? err.message
          : "Something went wrong while processing your payment."
      );
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="checkout-page">
      <div className="checkout-header">
        <button
          type="button"
          className="back-button"
          onClick={onBackToCart}
          aria-label="Back to cart"
        >
          &larr; Back to cart
        </button>
        <h1>Checkout</h1>
      </div>

      <div className="checkout-layout">
        <section className="cart-summary" aria-label="Order summary">
          <h2>Your order</h2>

          {items.length === 0 ? (
            <p className="empty-cart">Your cart is empty.</p>
          ) : (
            <ul className="cart-item-list">
              {items.map((item) => (
                <li key={item.id} className="cart-item">
                  <img
                    src={item.imageUrl}
                    alt={item.name}
                    className="cart-item-image"
                  />
                  <div className="cart-item-details">
                    <span className="cart-item-name">{item.name}</span>
                    <span className="cart-item-qty">
                      Qty: {item.quantity}
                    </span>
                  </div>
                  <span className="cart-item-price">
                    {formatPrice(item.unitPrice * item.quantity, currency)}
                  </span>
                </li>
              ))}
            </ul>
          )}

          <div className="cart-totals">
            <div className="cart-totals-row">
              <span>Subtotal</span>
              <span>{formatPrice(subtotal, currency)}</span>
            </div>
            <div className="cart-totals-row">
              <span>Shipping</span>
              <span>{formatPrice(shippingCost, currency)}</span>
            </div>
            <div className="cart-totals-row cart-totals-grand">
              <span>Total</span>
              <span>{formatPrice(total, currency)}</span>
            </div>
          </div>
        </section>

        <section className="delivery-form-section" aria-label="Delivery address">
          <h2>Delivery address</h2>

          <form
            className="delivery-form"
            onSubmit={handleSubmit}
            noValidate
          >
            <div className="form-row">
              <label htmlFor="fullName">Full name</label>
              <input
                id="fullName"
                type="text"
                value={address.fullName}
                onChange={handleChange("fullName")}
                aria-invalid={!!errors.fullName}
                aria-describedby={errors.fullName ? "fullName-error" : undefined}
              />
              {errors.fullName && (
                <span id="fullName-error" className="field-error">
                  {errors.fullName}
                </span>
              )}
            </div>

            <div className="form-row form-row-split">
              <div>
                <label htmlFor="email">Email</label>
                <input
                  id="email"
                  type="email"
                  value={address.email}
                  onChange={handleChange("email")}
                  aria-invalid={!!errors.email}
                  aria-describedby={errors.email ? "email-error" : undefined}
                />
                {errors.email && (
                  <span id="email-error" className="field-error">
                    {errors.email}
                  </span>
                )}
              </div>
              <div>
                <label htmlFor="phone">Phone</label>
                <input
                  id="phone"
                  type="tel"
                  value={address.phone}
                  onChange={handleChange("phone")}
                  aria-invalid={!!errors.phone}
                  aria-describedby={errors.phone ? "phone-error" : undefined}
                />
                {errors.phone && (
                  <span id="phone-error" className="field-error">
                    {errors.phone}
                  </span>
                )}
              </div>
            </div>

            <div className="form-row form-row-split">
              <div className="form-row-grow">
                <label htmlFor="street">Street</label>
                <input
                  id="street"
                  type="text"
                  value={address.street}
                  onChange={handleChange("street")}
                  aria-invalid={!!errors.street}
                  aria-describedby={errors.street ? "street-error" : undefined}
                />
                {errors.street && (
                  <span id="street-error" className="field-error">
                    {errors.street}
                  </span>
                )}
              </div>
              <div className="form-row-small">
                <label htmlFor="houseNumber">No.</label>
                <input
                  id="houseNumber"
                  type="text"
                  value={address.houseNumber}
                  onChange={handleChange("houseNumber")}
                  aria-invalid={!!errors.houseNumber}
                  aria-describedby={
                    errors.houseNumber ? "houseNumber-error" : undefined
                  }
                />
                {errors.houseNumber && (
                  <span id="houseNumber-error" className="field-error">
                    {errors.houseNumber}
                  </span>
                )}
              </div>
            </div>

            <div className="form-row">
              <label htmlFor="apartment">Apartment, suite, etc. (optional)</label>
              <input
                id="apartment"
                type="text"
                value={address.apartment}
                onChange={handleChange("apartment")}
              />
            </div>

            <div className="form-row form-row-split">
              <div>
                <label htmlFor="city">City</label>
                <input
                  id="city"
                  type="text"
                  value={address.city}
                  onChange={handleChange("city")}
                  aria-invalid={!!errors.city}
                  aria-describedby={errors.city ? "city-error" : undefined}
                />
                {errors.city && (
                  <span id="city-error" className="field-error">
                    {errors.city}
                  </span>
                )}
              </div>
              <div>
                <label htmlFor="postalCode">Postal code</label>
                <input
                  id="postalCode"
                  type="text"
                  value={address.postalCode}
                  onChange={handleChange("postalCode")}
                  aria-invalid={!!errors.postalCode}
                  aria-describedby={
                    errors.postalCode ? "postalCode-error" : undefined
                  }
                />
                {errors.postalCode && (
                  <span id="postalCode-error" className="field-error">
                    {errors.postalCode}
                  </span>
                )}
              </div>
            </div>

            <div className="form-row">
              <label htmlFor="country">Country</label>
              <input
                id="country"
                type="text"
                value={address.country}
                onChange={handleChange("country")}
                aria-invalid={!!errors.country}
                aria-describedby={errors.country ? "country-error" : undefined}
              />
              {errors.country && (
                <span id="country-error" className="field-error">
                  {errors.country}
                </span>
              )}
            </div>

            {submitError && (
              <div className="submit-error" role="alert">
                {submitError}
              </div>
            )}

            <div className="checkout-actions">
              <button
                type="button"
                className="secondary-button"
                onClick={onBackToCart}
                disabled={isSubmitting}
              >
                Back to cart
              </button>
              <button
                type="submit"
                className="pay-button"
                disabled={isSubmitting || items.length === 0}
              >
                {isSubmitting
                  ? "Processing..."
                  : `Pay ${formatPrice(total, currency)}`}
              </button>
            </div>
          </form>
        </section>
      </div>
    </div>
  );
};

export default CheckoutPage;
```

